parameters.jsCode:
// Validate webhook input + extract proposal_id
//
// Trigger: po WF_APPROVAL_GATE 'approved' callback s { proposal_id, approved_by }
//
// Output: payload pro GitHub branch + commit + PR creation

// ⛔ GitHub cíl se NEHÁDÁ: bez deklarovaného GITHUB_REPOSITORY (owner/repo) a
// https GITHUB_API_URL workflow odmítne commitovat — dosazené repo by zapisovalo
// do cizího repozitáře.
const githubRepository = String($env.GITHUB_REPOSITORY || '').trim();
if (!/^[A-Za-z0-9][A-Za-z0-9-]*\/[A-Za-z0-9_.-]+$/.test(githubRepository)) {
  throw new Error('GITHUB_REPOSITORY not configured (owner/repo) — refusing to commit to a guessed repository');
}
if (!String($env.GITHUB_API_URL || '').startsWith('https://')) {
  throw new Error('GITHUB_API_URL not configured (https)');
}

const body = $input.first().json.body || $input.first().json;
const proposalId = body.proposal_id;
const approvedBy = body.approved_by;

if (!proposalId) throw new Error('proposal_id required');

return [{
  json: {
    proposal_id: proposalId,
    approved_by: approvedBy || null,
    branch_name: `aisha/tooling/${proposalId}`,
    requested_at: new Date().toISOString(),
  },
}];

// Governance guard: resolve the proposal directly by id (no dependency on the
// pending-only RPC) and enforce that ONLY an 'approved' proposal may be committed.
//
// The human approval gate lives here: a proposal must have been moved to
// approval_status='approved' by an admin (update_tooling_proposal_status) before
// this committer will create a GitHub branch/file/PR. Any other status aborts.

const proposalId = $('Validate Input').item.json.proposal_id;
const rows = $('Fetch Artifact Content').item.json;
const row = Array.isArray(rows) ? rows[0] : (rows && rows[0]);

if (!row) {
  throw new Error(`Proposal ${proposalId} not found in aisha_tooling_proposals`);
}
if (row.approval_status !== 'approved') {
  throw new Error(
    `Proposal ${proposalId} has status '${row.approval_status}', expected 'approved' \u2014 only approved proposals may be committed`
  );
}

return [{
  json: {
    ...$('Validate Input').item.json,
    proposal_meta: row,
  },
}];

