parameters.jsCode:
// Hook-kind proposals need a SECOND artifact beyond the .sh file.
//
// Writing only `.claude/hooks/<name>.sh` is inert — Claude Code only fires a hook
// that is also registered in `.claude/settings.json` (an event entry with a matcher
// + a command pointing at the script). This node reads the branch's current
// settings.json (from the GitHub contents GET), idempotently merges in the new
// hook entry, and re-encodes it base64 for the follow-up commit.
//
// Event + matcher resolution (most specific wins):
//   1. metadata.settings_patch  { event, matcher, command }  (factory-rendered patch)
//   2. metadata.hook_event / metadata.hook_matcher
//   3. trigger_pattern.event / trigger_pattern.matcher
//   4. default: PreToolUse on Edit|Write|MultiEdit

const settingsResp = $input.first().json; // GitHub contents API GET response
const sha = settingsResp.sha;
const raw = Buffer.from(settingsResp.content || '', 'base64').toString('utf-8');

let settings;
try {
  settings = JSON.parse(raw);
} catch (e) {
  throw new Error('.claude/settings.json on branch is not valid JSON: ' + e.message);
}

const meta = $('Fetch Artifact Content').item.json[0];
const proposalId = $('Validate Input').item.json.proposal_id;
const artifactPath = meta.artifact_path; // e.g. .claude/hooks/prevent-x.sh
const triggerPattern = meta.trigger_pattern || {};
const metadata = meta.metadata || {};

const VALID_EVENTS = [
  'PreToolUse', 'PostToolUse', 'UserPromptSubmit', 'Notification',
  'Stop', 'SubagentStop', 'SessionStart', 'SessionEnd', 'PreCompact',
];

const patch = (metadata && typeof metadata.settings_patch === 'object' && metadata.settings_patch) || {};
let event = patch.event || metadata.hook_event || triggerPattern.event || 'PreToolUse';
if (!VALID_EVENTS.includes(event)) event = 'PreToolUse';
const matcher = patch.matcher || metadata.hook_matcher || triggerPattern.matcher || 'Edit|Write|MultiEdit';
const command = patch.command || ('${CLAUDE_PROJECT_DIR}/' + artifactPath);

// Idempotent merge — never double-add the same command under the same matcher.
settings.hooks = settings.hooks || {};
const eventArr = settings.hooks[event] = settings.hooks[event] || [];
let group = eventArr.find((g) => g && g.matcher === matcher);
const newHook = {
  type: 'command',
  command,
  _aisha: { kind: 'self-tooling', managed: true, proposal_id: proposalId },
};
let changed = false;
if (!group) {
  eventArr.push({ matcher, hooks: [newHook] });
  changed = true;
} else {
  group.hooks = group.hooks || [];
  if (!group.hooks.some((h) => h && h.command === command)) {
    group.hooks.push(newHook);
    changed = true;
  }
}

const merged = JSON.stringify(settings, null, 2) + '\n';

return [{
  json: {
    settings_sha: sha,
    settings_content_base64: Buffer.from(merged).toString('base64'),
    settings_changed: changed,
    hook_event: event,
    hook_matcher: matcher,
    hook_command: command,
  },
}];

